import os
from azure.servicebus import ServiceBusClient, ServiceBusReceivedMessage

def process_queue_and_dead_letter_failures(
    source_queue: str, 
    max_messages: int = 10, 
    max_wait_time: float = 5.0
) -> None:
    conn_str = os.environ["AZURE_SERVICE_BUS_CONNECTION_STRING"]

    with ServiceBusClient.from_connection_string(conn_str=conn_str) as client:
        with client.get_queue_receiver(queue_name=source_queue) as receiver:
            messages = receiver.receive_messages(
                max_message_count=max_messages, 
                max_wait_time=max_wait_time
            )

            for message in messages:
                try:
                    _execute_business_logic(message)
                    receiver.complete_message(message)
                except Exception as exc:
                    receiver.dead_letter_message(
                        message, 
                        reason=f"Failed processing: {exc}"
                    )

def _execute_business_logic(message: ServiceBusReceivedMessage) -> None:
    payload = message.body
    if not payload or payload == b"INVALID":
        raise ValueError("Message payload does not meet business requirements")
    print(f"Successfully processed message ID: {message.message_id}")
